def block(key, title, texts):
    return {"id": key, "title": title, "variants": [
        {"id": f"{key}-{i}", "template": text, "style": style}
        for i, (text, style) in enumerate(zip(texts, ["简洁直接", "温和自然", "正式完整"]))]}


